using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

using static Macaron.FactoryMethod.SourceGenerationHelper;

namespace Macaron.FactoryMethod;

[Generator]
public sealed class FactoryMethodGenerator : IIncrementalGenerator
{
    #region Constants
    private const string AutoFactoryAttributeSource =
        """
        // <auto-generated/>
        #nullable enable

        using System;
        using System.Diagnostics;

        namespace Macaron.FactoryMethod
        {
            [Conditional("SOURCE_GENERATOR_ONLY")]
            [AttributeUsage(AttributeTargets.Class | AttributeTargets.Struct)]
            internal sealed class AutoFactoryAttribute : Attribute
            {
                public bool IncludePrivateConstructors { get; set; }
            }
        }

        """;
    private const string FactoryMethodNameAttributeSource =
        """
        // <auto-generated/>
        #nullable enable

        using System;
        using System.Diagnostics;

        namespace Macaron.FactoryMethod
        {
            [Conditional("SOURCE_GENERATOR_ONLY")]
            [AttributeUsage(AttributeTargets.Constructor)]
            internal sealed class FactoryMethodNameAttribute : Attribute
            {
                public string Name { get; }

                public FactoryMethodNameAttribute(string name)
                {
                    Name = name;
                }
            }
        }

        """;
    private const string IgnoreAutoFactoryAttributeSource =
        """
        // <auto-generated/>
        #nullable enable

        using System;
        using System.Diagnostics;

        namespace Macaron.FactoryMethod
        {
            [Conditional("SOURCE_GENERATOR_ONLY")]
            [AttributeUsage(AttributeTargets.Constructor)]
            internal sealed class IgnoreAutoFactoryAttribute : Attribute
            {
            }
        }

        """;

    private const string AutoFactoryAttributeMetadataName = "Macaron.FactoryMethod.AutoFactoryAttribute";
    #endregion

    #region IIncrementalGenerator Interface
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static context =>
        {
            context.AddSource(
                hintName: "AutoFactoryAttribute.g.cs",
                sourceText: SourceText.From(AutoFactoryAttributeSource, Encoding.UTF8)
            );
            context.AddSource(
                hintName: "FactoryMethodNameAttribute.g.cs",
                sourceText: SourceText.From(FactoryMethodNameAttributeSource, Encoding.UTF8)
            );
            context.AddSource(
                hintName: "IgnoreAutoFactoryAttribute.g.cs",
                sourceText: SourceText.From(IgnoreAutoFactoryAttributeSource, Encoding.UTF8)
            );
        });

        var modelProvider = context
            .SyntaxProvider
            .ForAttributeWithMetadataName(
                fullyQualifiedMetadataName: AutoFactoryAttributeMetadataName,
                predicate: static (syntaxNode, _) => syntaxNode is TypeDeclarationSyntax,
                transform: static (attributeContext, cancellationToken) => SourceGenerationModelFactory.Create(
                    attributeContext,
                    cancellationToken
                )
            )
            .Where(static model => model != null)
            .Select(static (model, _) => model!);

        context.RegisterSourceOutput(
            source: modelProvider.Select(static (model, cancellationToken) =>
            {
                cancellationToken.ThrowIfCancellationRequested();

                return GenerateSource(model);
            }),
            action: static (sourceProductionContext, source) =>
            {
                sourceProductionContext.AddSource(
                    hintName: source.HintName,
                    sourceText: SourceText.From(source.Source, Encoding.UTF8)
                );
            }
        );
    }
    #endregion
}
